import {clock as nyClock,parseCandles,csvParse,research,defaults} from './engine.mjs';
const clockCache=new Map();
function clock(t){let value=clockCache.get(t);if(!value){value=nyClock(t);clockCache.set(t,value);}return value;}
export const studyConfig={version:'comparison-1',evaluationDays:['2026-11-02','2026-11-03','2026-11-04','2026-11-05','2026-11-06','2026-11-09','2026-11-10','2026-11-11'],trainingDays:['2026-10-23','2026-10-26','2026-10-27','2026-10-28','2026-10-29'],risk:100,maxContracts:3,dailyLoss:300,commission:1.24,slipTicks:1,start:'09:30',end:'11:30',flat:'16:00',openingRangeMinutes:15,atrPeriod:14,bandPeriod:20,bandSigma:2,flatSlopeATR:.25,pairLookback:60,pairEntryZ:2,pairExitZ:.5,pairMaxMinutes:30};
export const modelDefinitions=[
{id:'fvg-a',name:'FVG / 5m inversion',family:'FVG',data:'MNQ OHLC',direction:'Short only',status:'Tested',rules:'Existing A+ model: completed five-minute bullish-gap inversion after a recent fifteen-minute bearish-gap touch. Next-open short; five-bar swing stop + 1 point; fixed 2R target. Original gap age and minimum size rules retained.'},
{id:'fvg-b',name:'FVG / 1m continuation',family:'FVG',data:'MNQ OHLC',direction:'Short only',status:'Tested',rules:'Existing B model: one-minute bearish gap ≥ 1 point with a middle-candle bearish body ≥ 8 points, then a bearish retest. Next-open short; five-bar swing stop + 1 point; fixed 2R target.'},
{id:'orb',name:'Opening range breakout',family:'Breakout',data:'MNQ OHLC',direction:'Long / short',status:'Tested',rules:'Freeze the 09:30–09:44 range. First completed close ≥ 1 point above its high or below its low after 09:45. Enter next open, stop one ATR(14) from signal close, target 2R. One signal attempt per session.'},
{id:'vwap',name:'VWAP reversion',family:'Mean reversion',data:'MNQ OHLC + volume',direction:'Long / short',status:'Tested',rules:'RTH-reset VWAP approximation uses typical price × minute volume. After 20 bars, require a close back inside its volume-weighted ±2σ band following an outside close. VWAP 5-bar slope must be ≤ 0.25 ATR(14). Stop beyond the signal extreme by 0.5 ATR; target signal-time VWAP, frozen. Require planned reward/risk ≥ 0.5.'},
{id:'bands',name:'Bollinger reversion',family:'Mean reversion',data:'MNQ OHLC',direction:'Long / short',status:'Tested',rules:'20-close SMA ±2 population standard deviations. Require a completed close back inside after an outside close, and 5-bar SMA slope ≤ 0.25 ATR(14). Stop beyond the signal extreme by 0.5 ATR; target signal-time SMA, frozen. Require planned reward/risk ≥ 0.5.'},
{id:'fade',name:'Opening range fade',family:'Opening range fade',data:'MNQ OHLC',direction:'Long / short',status:'Tested',rules:'Freeze the 09:30–09:44 range. After a completed close outside by ≥ 1 point, wait for a close back inside. Fade toward the frozen range midpoint; stop 1 point beyond the excursion extreme. Require planned reward/risk ≥ 0.5. One signal attempt per session.'},
{id:'pairs',name:'MNQ / MES spread',family:'Pairs / spread',data:'Synchronized MNQ + MES OHLC',direction:'Two opposing legs',status:'Exploratory / separate fills',rules:'Freeze integer MES hedge quantity from five earlier complete sessions using average notional values: 1 MNQ versus round(2×mean MNQ / (5×mean MES)) MES. Dollar spread = 2×MNQ − 5×MES quantity×MES. Cross ±2 on an RTH-reset rolling 60-close z-score to fade it; close at |z| ≤ 0.5, a mean crossing, $100 close-based net stop, 30 minutes, or 16:00. All fills next synchronized open. Both legs incur costs. This is a spread hypothesis, not a cointegration test.'},
{id:'dom',name:'Order flow / DOM scalping',family:'Order flow',data:'Sequenced L2 updates + tape + queue model',direction:'Not specified',status:'Not tested / missing data',rules:'No order-book data was available. OHLC bars and trade volume cannot reconstruct resting depth, cancellations, queue priority, or tape timing. No hit rate or simulated DOM trades are generated.'}
];
export function parseStudyCSV(text){const bars=parseCandles(text),rows=csvParse(text),h=rows.shift().map(v=>v.toLowerCase()),vi=h.indexOf('volume');if(vi<0)throw Error('Study data require volume.');return bars.map((b,i)=>{const v=Number(rows[i][vi]);if(rows[i][vi]===''||!Number.isFinite(v)||v<0)throw Error('Invalid minute volume.');return {...b,v};});}
export function summarize(trades){let equity=0,peak=0,dd=0;const wins=trades.filter(t=>t.pnl>0),losses=trades.filter(t=>t.pnl<0),ties=trades.length-wins.length-losses.length,n=trades.length,p=n?wins.length/n:0,z=1.959963984540054;let interval=null;if(n){const d=1+z*z/n,center=(p+z*z/(2*n))/d,margin=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;interval=[(center-margin)*100,(center+margin)*100];}for(const t of trades){equity+=t.pnl;peak=Math.max(peak,equity);dd=Math.max(dd,peak-equity);}const gains=wins.reduce((s,t)=>s+t.pnl,0),loss=-losses.reduce((s,t)=>s+t.pnl,0);return {trades:n,wins:wins.length,losses:losses.length,breakeven:ties,hitRate:n?p*100:null,hitInterval:interval,net:equity,gross:trades.reduce((s,t)=>s+t.gross,0),fees:trades.reduce((s,t)=>s+(t.fees??(t.gross-t.pnl)),0),profitFactor:loss?gains/loss:null,averageWinner:wins.length?gains/wins.length:null,averageLoser:losses.length?loss/losses.length:null,realizedPayoff:wins.length&&losses.length?(gains/wins.length)/(loss/losses.length):null,maxDrawdown:dd,expectancy:n?equity/n:null};}
const tick=x=>Math.round(x*4)/4,up=x=>Math.ceil(x*4-1e-8)/4,down=x=>Math.floor(x*4+1e-8)/4;
function features(bs){let pv=0,p2v=0,vol=0,trs=[];return bs.map((b,i)=>{const tp=(b.h+b.l+b.c)/3;pv+=tp*b.v;p2v+=tp*tp*b.v;vol+=b.v;const vw=vol?pv/vol:null,sd=vol?Math.sqrt(Math.max(0,p2v/vol-vw*vw)):0;trs.push(Math.max(b.h-b.l,i?Math.abs(b.h-bs[i-1].c):0,i?Math.abs(b.l-bs[i-1].c):0));const atr=i>=13?trs.slice(i-13,i+1).reduce((a,b)=>a+b,0)/14:null,win=bs.slice(Math.max(0,i-19),i+1),ma=win.reduce((s,x)=>s+x.c,0)/win.length,std=Math.sqrt(win.reduce((s,x)=>s+(x.c-ma)**2,0)/win.length);return {vw,vs:sd,ma,sd:std,atr};});}
export function runSingleSession(bs,id,cfg){const f=features(bs),trades=[],signals=[],slip=cfg.slipTicks*.25;let p=null,pending=null,dayPnl=0,locked=false,attempted=false,excursion=null;const range=bs.filter(b=>{const hm=clock(b.t).hm;return hm>='09:30'&&hm<'09:45';});if(range.length!==15)return {trades,signals,excluded:'Incomplete opening range'};const high=Math.max(...range.map(b=>b.h)),low=Math.min(...range.map(b=>b.l)),mid=(high+low)/2;
function close(b,exit,reason){const gross=(exit-p.entry)*p.side*2*p.qty,fees=cfg.commission*p.qty,pnl=gross-fees;trades.push({...p,exit,exitTime:b.t,reason,gross,fees,pnl});dayPnl+=pnl;if(dayPnl<=-cfg.dailyLoss)locked=true;p=null;}
for(let i=0;i<bs.length;i++){const b=bs[i],hm=clock(b.t).hm,ft=f[i];
 if(p){if(hm>=cfg.flat)close(b,tick(b.o-p.side*slip),'Session close');else if(p.side===1?b.l<=p.stop:b.h>=p.stop)close(b,tick((p.side===1?Math.min(b.o,p.stop):Math.max(b.o,p.stop))-p.side*slip),'Stop');else if(p.side===1?b.h>=p.target:b.l<=p.target)close(b,p.target,'Target');}
 if(pending){const s=pending;pending=null;if(!p&&!locked&&hm>=cfg.start&&hm<cfg.end&&b.t===s.signalTime+60000){const entry=tick(b.o+s.side*slip),distance=(entry-s.stop)*s.side,target=s.target??tick(entry+s.side*distance*2),reward=(target-entry)*s.side,unitRisk=(distance+slip)*2+cfg.commission,budget=Math.min(cfg.risk,Math.max(0,cfg.dailyLoss+dayPnl)),qty=unitRisk>0?Math.min(cfg.maxContracts,Math.floor(budget/unitRisk)):0;s.entry=entry;s.stop=s.stop;s.target=target;s.qty=qty;s.plannedR=reward/distance;s.entryTime=b.t;s.risk=unitRisk*qty;const minR=id==='orb'?2:.5;if(distance<=0||reward<=0||s.plannedR<minR-1e-8||qty<1){s.status='Rejected';s.rejection=distance<=0?'Invalid stop':reward<=0?'Target crossed before entry':qty<1?'One contract exceeds risk budget':'Reward/risk below minimum';}else {s.status='Simulated';p={...s};if(s.side===1?b.l<=s.stop:b.h>=s.stop)close(b,tick((s.side===1?Math.min(b.o,s.stop):Math.max(b.o,s.stop))-s.side*slip),'Stop');else if(s.side===1?b.h>=target:b.l<=target)close(b,target,'Target');}}}
 if(hm<cfg.start||hm>=cfg.end||!ft.atr||locked)continue;
 let candidate=null;
 if(id==='orb'&&hm>='09:45'&&!attempted){if(b.c>=high+1||b.c<=low-1){attempted=true;const side=b.c>=high+1?1:-1;candidate={side,stop:side===1?down(b.c-ft.atr):up(b.c+ft.atr),context:{rangeHigh:high,rangeLow:low,atr:ft.atr}};}}
 if(id==='fade'&&hm>='09:45'&&!attempted){if(!excursion){if(b.c>=high+1)excursion={side:1,extreme:b.h};else if(b.c<=low-1)excursion={side:-1,extreme:b.l};}else {excursion.extreme=excursion.side===1?Math.max(excursion.extreme,b.h):Math.min(excursion.extreme,b.l);if(b.c<=high&&b.c>=low){attempted=true;candidate={side:-excursion.side,stop:excursion.side===1?up(excursion.extreme+1):down(excursion.extreme-1),target:tick(mid),context:{rangeHigh:high,rangeLow:low,excursionExtreme:excursion.extreme}};}}}
 if((id==='bands'||id==='vwap')&&i>=20){const prev=f[i-1],old=f[i-5],center=id==='bands'?ft.ma:ft.vw,sd=id==='bands'?ft.sd:ft.vs,pc=id==='bands'?prev.ma:prev.vw,ps=id==='bands'?prev.sd:prev.vs,oldcenter=id==='bands'?old.ma:old.vw;const flat=center!==null&&oldcenter!==null&&Math.abs(center-oldcenter)<=cfg.flatSlopeATR*ft.atr;if(flat&&sd>0&&ps>0){let side=0;if(bs[i-1].c<pc-2*ps&&b.c>=center-2*sd&&b.c<center)side=1;if(bs[i-1].c>pc+2*ps&&b.c<=center+2*sd&&b.c>center)side=-1;if(side)candidate={side,stop:side===1?down(b.l-.5*ft.atr):up(b.h+.5*ft.atr),target:tick(center),context:{center,sd,atr:ft.atr,slope:center-oldcenter}};}}
 if(candidate&&!p&&!pending){const s={model:id,signalTime:b.t,confirmedAt:b.t+60000,day:clock(b.t).day,status:'Await next candle',...candidate};signals.push(s);pending=s;}
}
if(p)close(bs.at(-1),tick(bs.at(-1).c-p.side*slip),'End of data');return {trades,signals};}
function hedge(nq,es,cfg){const maps=new Map(es.map(b=>[b.t,b]));const rows=nq.filter(b=>cfg.trainingDays.includes(clock(b.t).day)&&clock(b.t).hm>='09:30'&&clock(b.t).hm<='16:00'&&maps.has(b.t));if(rows.length<391*5)throw Error('Five complete paired training sessions required.');const n=rows.reduce((s,b)=>s+b.c,0)/rows.length,e=rows.reduce((s,b)=>s+maps.get(b.t).c,0)/rows.length;return {nqQty:1,esQty:Math.max(1,Math.round(2*n/(5*e))),meanMNQ:n,meanMES:e,observations:rows.length,trainingDays:cfg.trainingDays};}
function pairRun(nq,es,h,cfg){const map=new Map(es.map(b=>[b.t,b])),rows=nq.filter(b=>map.has(b.t)).map(b=>({n:b,e:map.get(b.t),t:b.t}));let history=[],p=null,pending=null,exitPending=null,dayPnl=0,locked=false,prevZ=null;const trades=[],signals=[],slip=cfg.slipTicks*.25;
function prices(r,side,entry){return {n:tick(r.n.o+(entry?1:-1)*side*slip),e:tick(r.e.o-(entry?1:-1)*side*slip)};}
function netAt(r){const exit={n:tick(r.n.c-p.side*slip),e:tick(r.e.c+p.side*slip)};return (exit.n-p.entryNQ)*p.side*2+(exit.e-p.entryMES)*(-p.side)*5*h.esQty-cfg.commission*(1+h.esQty);}
function close(r,reason){const x=prices(r,p.side,false),gross=(x.n-p.entryNQ)*p.side*2+(x.e-p.entryMES)*(-p.side)*5*h.esQty,fees=cfg.commission*(1+h.esQty),pnl=gross-fees;trades.push({...p,exitTime:r.t,exitNQ:x.n,exitMES:x.e,reason,gross,fees,pnl,legs:[{symbol:'MNQ=F',qty:1,side:p.side,entry:p.entryNQ,exit:x.n,multiplier:2},{symbol:'MES=F',qty:h.esQty,side:-p.side,entry:p.entryMES,exit:x.e,multiplier:5}]});dayPnl+=pnl;if(dayPnl<=-cfg.dailyLoss)locked=true;p=null;exitPending=null;}
for(const r of rows){const hm=clock(r.t).hm;if(p&&(exitPending||hm>=cfg.flat||r.t-p.entryTime>=cfg.pairMaxMinutes*60000)){close(r,exitPending|| (hm>=cfg.flat?'Session close':'Time limit'));}if(pending){const s=pending;pending=null;if(!p&&!locked&&hm<cfg.end&&r.t===s.signalTime+60000){const x=prices(r,s.side,true),cost=cfg.commission*(1+h.esQty)+2*slip*(2+5*h.esQty);if(cost>=Math.min(cfg.risk,cfg.dailyLoss+dayPnl)){s.status='Rejected';s.rejection='Trading costs exceed remaining budget';}else {s.status='Simulated';p={model:'pairs',side:s.side,signalTime:s.signalTime,confirmedAt:s.confirmedAt,entryTime:r.t,entryNQ:x.n,entryMES:x.e,qty:1,esQty:h.esQty,day:clock(r.t).day,entryZ:s.z,nominalStopBudget:Math.min(cfg.risk,cfg.dailyLoss+dayPnl),context:s.context};}}}
const spread=2*r.n.c-5*h.esQty*r.e.c;history.push(spread);if(history.length>cfg.pairLookback)history.shift();if(history.length<cfg.pairLookback)continue;const mean=history.reduce((s,x)=>s+x,0)/history.length,sd=Math.sqrt(history.reduce((s,x)=>s+(x-mean)**2,0)/history.length),z=sd?(spread-mean)/sd:0;
if(p){if(netAt(r)<=-p.nominalStopBudget)exitPending='Close-based stop';else if(Math.abs(z)<=cfg.pairExitZ||p.side*z>=0)exitPending='Spread reversion';}
if(!p&&!pending&&!locked&&hm>=cfg.start&&hm<cfg.end&&prevZ!==null&&Math.abs(prevZ)<cfg.pairEntryZ&&Math.abs(z)>=cfg.pairEntryZ){const s={model:'pairs',signalTime:r.t,confirmedAt:r.t+60000,day:clock(r.t).day,z,side:z>0?-1:1,status:'Await next candle',context:{spread,mean,sd,hedgeMES:h.esQty}};signals.push(s);pending=s;}prevZ=z;
}
if(p)close(rows.at(-1),'End of data');return {trades,signals};}
export function runComparison(nq,es,config=studyConfig){const cfg={...studyConfig,...config};const h=hedge(nq,es,cfg),results=[];for(const model of modelDefinitions){if(model.id==='dom'){results.push({...model,stats:null,trades:[],signals:[],daily:[],reason:'No historical L2 order-book updates or queue data were obtained.'});continue;}const trades=[],signals=[],daily=[];for(const day of cfg.evaluationDays){const full=nq.filter(b=>clock(b.t).day===day&&clock(b.t).hm<=cfg.flat),rth=full.filter(b=>clock(b.t).hm>=cfg.start),other=es.filter(b=>clock(b.t).day===day&&clock(b.t).hm>=cfg.start&&clock(b.t).hm<=cfg.flat);if(rth.length!==391||other.length!==391)throw Error('Incomplete common session '+day);for(let i=1;i<rth.length;i++)if(rth[i].t-rth[i-1].t!==60000||other[i].t-other[i-1].t!==60000)throw Error('Noncontiguous session '+day);let r;if(model.id.startsWith('fvg')){const x=research(full,{...defaults,setup:model.id==='fvg-a'?'A':'B',risk:cfg.risk,maxContracts:cfg.maxContracts,dailyLoss:cfg.dailyLoss,commission:cfg.commission,slipTicks:cfg.slipTicks,sessionStart:cfg.start,sessionEnd:cfg.end});r={trades:x.trades.map(t=>({...t,model:model.id,side:-1,day,fees:t.gross-t.pnl,confirmedAt:t.signalTime+60000})),signals:x.signals.map(s=>({...s,model:model.id,signalTime:s.t,confirmedAt:s.t+60000,day}))};}else if(model.id==='pairs')r=pairRun(rth,other,h,cfg);else r=runSingleSession(rth,model.id,cfg);trades.push(...r.trades);signals.push(...r.signals);daily.push({day,...summarize(r.trades),signals:r.signals.length});}results.push({...model,stats:summarize(trades),trades,signals,daily});}return {config:cfg,hedge:h,results};}
